import * as http from 'node:http';
import * as net from 'node:net';
function main(): void {
  const server = http.createServer((req: any, res: any): void => {
    req.on('data', (): void => { console.log('data'); });
    req.on('end', (): void => { console.log('end'); });
  });
  server.listen(0, (): void => {
    const client = net.connect((server.address() as any).port);
    let response = '';
    client.setEncoding('utf8');
    client.on('data', (chunk: any): void => { response += chunk; });
    client.on('end', (): void => {
      console.log(JSON.stringify(response));
      server.close();
    });
    client.write('POST / HTTP/1.1\r\nHost: a\r\nConnection: close\r\nTransfer-Encoding: chunked\r\n\r\n5\r\r;ABCD\r\n34\r\nE\r\n0\r\n\r\n');
    client.resume();
  });
}
